def intersection_nested_lists(l1, l2):
    """Write a function to find the nested list elements which are present in another list."""
    try:
        members = set(l1)
    except TypeError:
        return [[item for item in sublist if item in l1] for sublist in l2]
    return [[item for item in sublist if item in members] for sublist in l2]
